jax2tf.convert can be used as a decorator at the moment:
@jax2tf.convert
def my_function(inputs):
  # ...

This is nice, but if I want to pass in any arguments, it no longer works. The following code fails with

Invalid keyword argument with_gradients to function jax.experimental.jax2tf.convert [wrong-keyword-args]
Expected: (fun, *, enable_xla, in_shapes, with_gradient)
Actually passed: (with_gradients)"

@jax2tf.convert(with_gradient=False)
def my_function(inputs):
  # ...

To resolve that, you could introduce a method like:
def convert_with(fun, **kwargs):
  return functools.partial(convert, **kwargs)

which would allow code like:
@jax2tf.convert_with(with_gradient=False)
def my_function(inputs):
  # ...

Perhaps my understanding of the mechanics of lax.cond but it is unclear to me while  the following code results in "maximum recursion depth exceeded while calling a Python object" error
from jax import numpy as jnp 
from jax import lax
def diag_kron_lax(diag_operators):
    length = diag_operators.shape[0]

    def true_branch(_):
        return diag_operators.reshape(-1)

    def false_branch(_):
        oper1 = diag_kron_lax(diag_operators[:length//2])
        oper2 = diag_kron_lax(diag_operators[length//2:])
        return jnp.einsum('i,j->ij', oper1, oper2).reshape(-1)


    return lax.cond(length==1, true_branch, false_branch, operand=None)

diag_kron_lax(jnp.arange(10).reshape(2,-1))
while an equivalent pythonic version for scan (according to the documentation) works fine?
from jax import numpy as jnp 
from jax import lax
def cond(pred, true_fun, false_fun, operand):
  if pred:
    return true_fun(operand)
  else:
    return false_fun(operand)

def diag_kron_my(diag_operators):
    length = diag_operators.shape[0]
    def true_branch(_):
        return diag_operators.reshape(-1)

    def false_branch(_):
        oper1 = diag_kron_my(diag_operators[:length//2])
        oper2 = diag_kron_my(diag_operators[length//2:])
        return jnp.einsum('i,j->ij', oper1, oper2).reshape(-1)


    return cond(length==1, true_branch, false_branch, operand=None)

diag_kron_my(jnp.arange(10).reshape(2,-1))
